async function api(path,body){const t=token();if(!t)throw Error('Bitte mit deinem Owner-Konto anmelden.');const r=await fetch(API+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+t,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',signal:AbortSignal.timeout(15000)});let d;try{d=await r.json()}catch{throw Error('Sicherheitszentrale antwortet nicht lesbar.')}if(!r.ok){const e=Error(d.error||'Sicherheitszentrale nicht verfügbar');e.denied=r.status===401||r.status===403;if(e.denied){authorized='';state=null;lastContext=null;pendingByDevice.clear();content.replaceChildren();access()}throw e}if(t!==token())throw Error('Anmeldung hat sich geändert.');return d}
